import { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { useNavigate, useParams } from "react-router-dom";
import CheckIcon from "@mui/icons-material/Check";
import SearchIcon from "@mui/icons-material/Search";
import CloseIcon from "@mui/icons-material/Close";
import KeyboardArrowDown from "@mui/icons-material/KeyboardArrowDown";
import GroupsIcon from "@mui/icons-material/Groups";
import SettingsIcon from "@mui/icons-material/Settings";
import BarChartIcon from "@mui/icons-material/BarChart";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import PeopleAltIcon from "@mui/icons-material/PeopleAlt";
import HowToRegIcon from "@mui/icons-material/HowToReg";
import { getProgrammes, getAttendance, getAttendanceSummary, getRoutes, getRoute, getDelegates, markAttendance, toggleReady } from "../../services/api";
import { joinProgramme, leaveProgramme, onAttendanceUpdated } from "../../services/socket";
import { timeAgo } from "../../services/utils";
import { useConnectivity } from "../../hooks/useConnectivity";
import EmptyState from "../../components/shared/EmptyState";

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

const FILTERS = ["All", "Missing", "Present"];

export function AdminDashboard() {
    const navigate = useNavigate();
    const { routeId } = useParams();
    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }
    if (currentUser.role !== 'staff') {
        navigate('/');
        return null;
    }

    const [programmes, setProgrammes] = useState([]);
    const [programmeId, setProgrammeId] = useState(null);
    const [showPicker, setShowPicker] = useState(false);
    const [summary, setSummary] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [routes, setRoutes] = useState([]);
    const [selectedRoute, setSelectedRoute] = useState(null);
    const [allDelegates, setAllDelegates] = useState([]);
    const [search, setSearch] = useState("");
    const [filter, setFilter] = useState("All");
    const [selected, setSelected] = useState(null);
    const [noteText, setNoteText] = useState("");
    const [tick, setTick] = useState(0);
    const { isOnline } = useConnectivity();
    const allDelegatesRef = useRef(allDelegates);
    allDelegatesRef.current = allDelegates;
    const routesRef = useRef(routes);
    routesRef.current = routes;

    useEffect(() => {
        getProgrammes()
            .then((list) => {
                setProgrammes(list);
                if (list.length > 0) setProgrammeId(list[0].id);
            })
            .catch((e) => setError(e.message))
            .finally(() => setLoading(false));
    }, []);

    const loadData = useCallback(async (id) => {
        if (!id) return;
        setLoading(true);
        setError(null);
        try {
            const [att, summ] = await Promise.all([
                getAttendance(id),
                getAttendanceSummary(id),
            ]);
            setSummary(summ);
        } catch (e) {
            setError(e.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        if (programmeId) {
            loadData(programmeId);
            joinProgramme(programmeId);
            getRoutes(programmeId).then(setRoutes).catch(() => {});
            getDelegates(programmeId).then(setAllDelegates).catch(() => {});
            return () => leaveProgramme(programmeId);
        }
    }, [programmeId, loadData]);

    // Deep-link: load route from URL param on mount / programme change
    useEffect(() => {
        if (!programmeId || !routeId || !routes.length) return;
        const match = routes.find((r) => r.id === routeId);
        if (match) {
            getRoute(programmeId, routeId).then(setSelectedRoute).catch(() => {});
        }
        // eslint-disable-next-line
    }, [programmeId, routeId, routes.length]);

    useEffect(() => {
        return onAttendanceUpdated((event) => {
            if (event.programmeId !== programmeId) return;
            const delegate = allDelegatesRef.current.find((d) => d.id === event.delegateId);
            const delegateRouteIds = delegate?.routeIds || [];
            setAllDelegates((prev) => prev.map((d) =>
                d.id === event.delegateId
                    ? { ...d, status: event.status, method: event.method, checkedInAt: event.checkedInAt }
                    : d
            ));
            setSummary((prev) => prev ? {
                ...prev,
                checkedIn: event.status === "present" ? prev.checkedIn + 1 : prev.checkedIn - 1,
                missing: event.status === "present" ? prev.missing - 1 : prev.missing + 1,
            } : prev);
            setRoutes((prev) => prev.map((r) =>
                delegateRouteIds.includes(r.id)
                    ? { ...r, checkedIn: event.status === "present" ? r.checkedIn + 1 : r.checkedIn - 1 }
                    : r
            ));
            setSelectedRoute((prev) =>
                prev && delegateRouteIds.includes(prev.id)
                    ? { ...prev, checkedIn: event.status === "present" ? prev.checkedIn + 1 : prev.checkedIn - 1 }
                    : prev
            );
        });
    }, [programmeId]);

    useEffect(() => {
        const onSyncDone = () => {
            if (programmeId) {
                loadData(programmeId);
                getRoutes(programmeId).then(setRoutes).catch(() => {});
                getDelegates(programmeId).then(setAllDelegates).catch(() => {});
            }
        };
        window.addEventListener('sync:done', onSyncDone);
        return () => window.removeEventListener('sync:done', onSyncDone);
    }, [programmeId, loadData]);

    useEffect(() => {
        const id = setInterval(() => setTick((t) => t + 1), 10000);
        return () => clearInterval(id);
    }, []);

    const handleProgrammeChange = (id) => {
        setProgrammeId(id);
        setSelectedRoute(null);
        setSelected(null);
        setSearch("");
        setShowPicker(false);
    };

    const handleToggleReady = async (routeId) => {
        if (!programmeId) return;
        const route = routes.find((r) => r.id === routeId);
        if (!route) return;
        const next = !route.ready;
        try {
            await toggleReady(programmeId, routeId, { ready: next });
            setRoutes((prev) => prev.map((r) => r.id === routeId ? { ...r, ready: next } : r));
            setSelectedRoute((prev) => prev?.id === routeId ? { ...prev, ready: next } : prev);
        } catch (e) {
            setError(e.message);
        }
    };

    const handleSelectRoute = async (route) => {
        if (selectedRoute?.id === route.id) {
            setSelectedRoute(null);
            setSearch("");
            setFilter("All");
            navigate(`/dashboard`, { replace: true });
            return;
        }
        try {
            const full = await getRoute(programmeId, route.id);
            setSelectedRoute(full);
            navigate(`/dashboard/routes/${route.id}`, { replace: true });
        } catch (e) {
            setError(e.message);
        }
    };

    const handleCheckIn = async (id, notes = "") => {
        try {
            await markAttendance(programmeId, id, { status: "present", method: "manual", notes });
            setNoteText("");
            if (!navigator.onLine) {
                const delegate = allDelegatesRef.current.find(d => d.id === id);
                const delegateRouteIds = delegate?.routeIds || [];
                setAllDelegates(prev => prev.map(d =>
                    d.id === id ? { ...d, status: "present", method: "manual", checkedInAt: new Date().toISOString() } : d
                ));
                setSummary(prev => prev ? { ...prev, checkedIn: prev.checkedIn + 1, missing: prev.missing - 1 } : prev);
                setRoutes(prev => prev.map(r =>
                    delegateRouteIds.includes(r.id) ? { ...r, checkedIn: r.checkedIn + 1 } : r
                ));
                setSelectedRoute(prev =>
                    prev && delegateRouteIds.includes(prev.id)
                        ? { ...prev, checkedIn: prev.checkedIn + 1 }
                        : prev
                );
            }
        } catch (e) {
            setError(e.message);
        }
    };

    const handleUndo = async (id) => {
        try {
            await markAttendance(programmeId, id, { status: "absent", method: "manual", notes: "" });
        } catch (e) {
            setError(e.message);
        }
        setNoteText("");
        if (!navigator.onLine) {
            const delegate = allDelegatesRef.current.find(d => d.id === id);
            const delegateRouteIds = delegate?.routeIds || [];
            setAllDelegates(prev => prev.map(d =>
                d.id === id ? { ...d, status: "absent", method: null, checkedInAt: null } : d
            ));
            setSummary(prev => prev ? { ...prev, checkedIn: prev.checkedIn - 1, missing: prev.missing + 1 } : prev);
            setRoutes(prev => prev.map(r =>
                delegateRouteIds.includes(r.id) ? { ...r, checkedIn: r.checkedIn - 1 } : r
            ));
            setSelectedRoute(prev =>
                prev && delegateRouteIds.includes(prev.id)
                    ? { ...prev, checkedIn: prev.checkedIn - 1 }
                    : prev
            );
        }
    };

    const currentProgramme = programmes.find((p) => p.id === programmeId);

    const checkedMap = useMemo(() => {
        const map = {};
        allDelegates.forEach((d) => { map[d.id] = d.status === "present"; });
        return map;
    }, [allDelegates]);

    const routeDelegates = useMemo(() => {
        let list = allDelegates;
        if (selectedRoute) list = list.filter((d) => d.routeIds?.includes(selectedRoute.id));
        if (search.trim()) {
            const q = search.toLowerCase();
            list = list.filter((d) => d.name.toLowerCase().includes(q));
        }
        if (filter === "Missing") list = list.filter((d) => !checkedMap[d.id]);
        else if (filter === "Present") list = list.filter((d) => checkedMap[d.id]);
        return [...list].sort((a, b) => (checkedMap[a.id] === checkedMap[b.id] ? 0 : checkedMap[a.id] ? 1 : -1));
    }, [allDelegates, selectedRoute, search, filter, checkedMap]);

    const routeMissing = routeDelegates.filter((d) => !checkedMap[d.id]).length;

    const handleBackdrop = (e) => { if (e.target === e.currentTarget) { setSelected(null); setNoteText(""); } };

    useEffect(() => {
        if (!selected) return;
        const onKey = (e) => { if (e.key === "Escape") { setSelected(null); setNoteText(""); } };
        window.addEventListener("keydown", onKey);
        return () => window.removeEventListener("keydown", onKey);
    }, [selected]);

    const isPresent = selected ? checkedMap[selected.id] : false;

    if (loading && programmes.length === 0) {
        return (
            <main className="page">
                <div className="mx-auto w-full max-w-2xl space-y-3 px-4 pt-8 sm:px-6">
                    <div className="skeleton h-6 w-40" />
                    <div className="skeleton-card">
                        <div className="skeleton-text mb-3 w-2/3" />
                        <div className="skeleton-text w-full" />
                    </div>
                    <div className="skeleton-card">
                        <div className="skeleton-text mb-3 w-1/2" />
                        <div className="skeleton h-2 w-full" />
                        <div className="skeleton-text mt-3 w-1/3" />
                    </div>
                    <div className="skeleton-card">
                        <div className="skeleton-text mb-3 w-1/2" />
                        <div className="skeleton h-2 w-full" />
                        <div className="skeleton-text mt-3 w-1/3" />
                    </div>
                </div>
            </main>
        );
    }

    if (error && programmes.length === 0) {
        return (
            <main className="page">
                <div className="mx-auto w-full max-w-2xl px-4 pt-8 sm:px-6">
                    <div className="banner banner-error">
                        <span>{error}</span>
                        <button className="btn btn-secondary btn-sm" onClick={() => setError(null)}>Dismiss</button>
                    </div>
                </div>
            </main>
        );
    }

    if (programmes.length === 0) {
        return (
            <main className="page">
                <div className="mx-auto w-full max-w-2xl px-4 sm:px-6">
                    <EmptyState
                        icon={<CheckCircleIcon />}
                        title="No programmes yet"
                        desc="Create your first programme to start tracking attendance."
                        action={<button className="btn btn-primary btn-sm" onClick={() => navigate("/programmes")}>Create Programme</button>}
                    />
                </div>
            </main>
        );
    }

    const checked = summary?.checkedIn ?? 0;
    const total = summary?.total ?? 0;

    return (
        <main className="page">
            {error && (
                <div className="mx-auto mb-2 w-full max-w-2xl px-4 sm:px-6">
                    <div className="banner banner-error">
                        <span>{error}</span>
                        <button className="btn btn-secondary btn-sm" onClick={() => setError(null)}>Dismiss</button>
                    </div>
                </div>
            )}
            <header className="topbar">
                <div className="topbar-content">
                    {selectedRoute ? (
                        <div className="flex min-w-0 flex-1 items-center gap-2">
                            <button
                                className="btn btn-ghost btn-sm shrink-0 whitespace-nowrap"
                                onClick={() => { setSelectedRoute(null); setSearch(""); setFilter("All"); navigate("/dashboard", { replace: true }); }}
                            >
                                All Routes
                            </button>
                            <span className="title truncate">{selectedRoute.name}</span>
                        </div>
                    ) : (
                        <button
                            className="flex min-w-0 flex-1 items-center gap-2 rounded-xl border border-edge bg-surface px-3.5 py-2.5 text-left transition-colors hover:bg-surface-2"
                            onClick={() => setShowPicker((p) => !p)}
                        >
                            <span className="truncate text-sm font-semibold text-ink">{currentProgramme?.name || "Select programme"}</span>
                            <KeyboardArrowDown
                                className={`shrink-0 text-muted transition-transform ${showPicker ? "rotate-180" : ""}`}
                            />
                        </button>
                    )}
                    <div className="header-actions">
                        <button
                            className="btn btn-icon btn-secondary"
                            onClick={() => navigate("/directory")}
                            aria-label="Delegate directory"
                        >
                            <PeopleAltIcon />
                        </button>
                        <button
                            className="btn btn-icon btn-secondary"
                            onClick={() => navigate(`/summary/${programmeId}`)}
                            aria-label="View report"
                        >
                            <BarChartIcon />
                        </button>
                        <button
                            className="btn btn-icon btn-secondary"
                            onClick={() => navigate("/programmes")}
                            aria-label="Manage programmes"
                        >
                            <SettingsIcon />
                        </button>
                    </div>
                </div>
                {currentProgramme && (
                    <p className="meta mt-1">
                        {currentProgramme.startDate} – {currentProgramme.endDate}
                    </p>
                )}
            </header>

            {showPicker && (
                <div className="mx-auto mb-3 w-full max-w-2xl px-4 sm:px-6">
                    <div className="card card-divide">
                        {programmes.map((p) => (
                            <button
                                key={p.id}
                                className={`row row-clickable w-full text-left ${p.id === programmeId ? "bg-accent/10" : ""}`}
                                onClick={() => handleProgrammeChange(p.id)}
                            >
                                <span className={`row-title ${p.id === programmeId ? "text-accent" : ""}`}>{p.name}</span>
                                <span className="row-meta shrink-0">{p.checkedIn}/{p.totalDelegates}</span>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            <div className="mx-auto w-full max-w-2xl space-y-3 px-4 pb-3 sm:px-6">
                {selectedRoute && (
                    <div className="card-pad">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <GroupsIcon className="text-muted" />
                                <span className="meta">Delegates</span>
                            </div>
                            <div className="flex items-center gap-3">
                                <div className="flex items-baseline gap-1">
                                    <span className="display">{selectedRoute.checkedIn}/{selectedRoute.delegateCount}</span>
                                    <span className="meta">checked in</span>
                                </div>
                                {selectedRoute.delegateCount - selectedRoute.checkedIn > 0 && (
                                    <span className="pill pill-warn">
                                        {selectedRoute.delegateCount - selectedRoute.checkedIn} missing
                                    </span>
                                )}
                            </div>
                        </div>
                    </div>
                )}
                {!selectedRoute && (
                    <div className="card-pad flex flex-col items-center gap-1">
                        <div className="flex items-center gap-2">
                            <GroupsIcon className="text-accent" />
                            <span className="display">{checked}/{total}</span>
                        </div>
                        <span className="meta">checked in</span>
                    </div>
                )}
            </div>

            {!selectedRoute && (
                <div className="mx-auto w-full max-w-2xl space-y-2 px-4 pb-4 sm:px-6">
                    {routes.length === 0 ? (
                        <EmptyState
                            icon={<GroupsIcon />}
                            title="No routes yet"
                            desc="Routes will appear here once they are added."
                        />
                    ) : routes.map((r) => {
                    const pct = r.delegateCount > 0 ? Math.round((r.checkedIn / r.delegateCount) * 100) : 0;
                    const isSelected = selectedRoute?.id === r.id;
                    return (
                        <div
                            key={r.id}
                            className={`card cursor-pointer px-4 py-3.5 transition-colors ${isSelected ? "border-accent bg-accent/10" : "hover:border-accent/40"}`}
                            onClick={() => handleSelectRoute(r)}
                        >
                            <div className="mb-2 flex items-start justify-between gap-2">
                                <div className="flex min-w-0 items-center gap-1.5">
                                    <span className="title truncate">{r.name}</span>
                                </div>
                                {r.ready ? (
                                    <span className="pill pill-ok shrink-0">Ready to depart</span>
                                ) : isSelected ? (
                                    <span className="pill pill-accent shrink-0">active</span>
                                ) : (
                                    <span className="pill pill-warn shrink-0">pending</span>
                                )}
                            </div>
                            <div className="progress">
                                <div className={`progress-fill ${r.ready ? "bg-ok" : ""}`} style={{ width: `${pct}%` }} />
                            </div>
                            <div className="mt-1.5 flex justify-between gap-2">
                                <span className="meta truncate text-ok">{r.checkedIn} checked in</span>
                                {!r.ready && r.delegateCount - r.checkedIn > 0 && (
                                    <span className="meta shrink-0 text-warn" onClick={(e) => e.stopPropagation()}>{r.delegateCount - r.checkedIn} missing</span>
                                )}
                            </div>
                        </div>
                    );
                })}
                    </div>
                )}

            {selectedRoute && (
                <div className="mx-auto w-full max-w-2xl space-y-3 px-4 pb-4 sm:px-6">
                    {/* Search & filter */}
                    <div>
                        <div className="flex items-center gap-2">
                            <div className="search-box flex-1">
                                <SearchIcon className="search-icon" />
                                <input
                                    type="text"
                                    placeholder="Search delegates..."
                                    value={search}
                                    onChange={(e) => setSearch(e.target.value)}
                                    className="search-input"
                                />
                                {search && (
                                    <button className="search-clear" onClick={() => setSearch("")}>
                                        <CloseIcon />
                                    </button>
                                )}
                            </div>
                        </div>
                        <div className="mt-3 flex gap-2">
                            {FILTERS.map((f) => (
                                <button
                                    key={f}
                                    className={`filter-chip ${f === filter ? "filter-chip-active" : ""}`}
                                    onClick={() => setFilter(f)}
                                >
                                    {f}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Delegate list */}
                    <div>
                        {routeDelegates.length === 0 ? (
                            <EmptyState
                                icon={<PeopleAltIcon />}
                                title="No delegates found"
                                desc="Try a different search or filter."
                            />
                        ) : (
                            <ul className="card card-divide">
                                {routeDelegates.map((d) => {
                                    const present = checkedMap[d.id];
                                    return (
                                        <li
                                            key={d.id}
                                            className="row row-clickable"
                                            onClick={() => { setSelected(d); setNoteText(""); }}
                                        >
                                            <div className="row-left">
                                                <div className={`avatar avatar-sm ${present ? "avatar-ok" : "avatar-warn"}`}>
                                                    {d.name.charAt(0)}
                                                </div>
                                                <div className="row-text">
                                                    <span className="row-title">{d.name}</span>
                                                    <span className={`row-meta ${present ? "text-ok" : ""}`}>
                                                        {present
                                                            ? d.method === "auto" ? "Checked in (auto)" : "Checked in (manual)"
                                                            : d.notes || "Not checked in"}
                                                    </span>
                                                </div>
                                            </div>
                                            <div className="row-actions" onClick={(e) => e.stopPropagation()}>
                                                {present ? (
                                                    <button className="btn btn-secondary btn-sm" onClick={() => handleUndo(d.id)}>
                                                        Undo
                                                    </button>
                                                ) : (
                                                    <button className="btn btn-primary btn-sm" onClick={() => handleCheckIn(d.id)}>
                                                        <CheckIcon />
                                                        Check in
                                                    </button>
                                                )}
                                            </div>
                                        </li>
                                    );
                                })}
                            </ul>
                        )}
                    </div>

                    {/* Profile sheet */}
                    {selected && (
                        <div className="sheet-backdrop" onClick={handleBackdrop}>
                            <div className="sheet">
                                <div className="sheet-handle" />
                                <div className="sheet-header">
                                    <div className="min-w-0">
                                        <h3 className="sheet-title">{selected.name}</h3>
                                        <p className="sheet-sub">{selected.badge || "No badge"}</p>
                                    </div>
                                    <button className="sheet-close" onClick={() => { setSelected(null); setNoteText(""); }}>
                                        X
                                    </button>
                                </div>
                                <div className="sheet-body">
                                    <div className="mb-4 flex flex-col items-center gap-2">
                                        <div className={`avatar avatar-lg ${isPresent ? "avatar-ok" : "avatar-warn"}`}>
                                            {selected.name.charAt(0)}
                                        </div>
                                        <span className={`pill ${isPresent ? "pill-ok" : "pill-warn"}`}>
                                            {isPresent ? "Checked in" : "Not checked in"}
                                        </span>
                                    </div>
                                    <div className="space-y-3">
                                        <div className="flex items-center justify-between gap-3">
                                            <span className="meta">Route</span>
                                            <span className="text-sm font-medium text-ink">{selected.routeName || "---"}</span>
                                        </div>
                                        {isPresent && selected.method && (
                                            <div className="flex items-center justify-between gap-3">
                                                <span className="meta">Checked in</span>
                                                <span className="text-sm font-medium text-ink">{timeAgo(selected.checkedInAt)}</span>
                                            </div>
                                        )}
                                        {isPresent && selected.method && (
                                            <div className="flex items-center justify-between gap-3">
                                                <span className="meta">Method</span>
                                                <span className="text-sm font-medium text-ink">
                                                    {selected.method === "auto" ? "Facial recognition" : "Manual check-in"}
                                                </span>
                                            </div>
                                        )}
                                        {!isPresent && selected.notes && (
                                            <div className="flex items-center justify-between gap-3">
                                                <span className="meta">Note</span>
                                                <span className="text-sm font-medium text-ink">{selected.notes}</span>
                                            </div>
                                        )}
                                    </div>
                                    {!isPresent && (
                                        <div className="mt-4">
                                            <input
                                                className="input"
                                                placeholder="Add a note (e.g. badge missing, verified by photo)"
                                                value={noteText}
                                                onChange={(e) => setNoteText(e.target.value)}
                                            />
                                        </div>
                                    )}
                                </div>
                                <div className="sheet-footer">
                                    {isPresent ? (
                                        <button className="btn btn-secondary btn-block btn-lg" onClick={() => { handleUndo(selected.id); setSelected(null); setNoteText(""); }}>
                                            Mark as Absent
                                        </button>
                                    ) : (
                                        <button className="btn btn-primary btn-block btn-lg" onClick={() => { handleCheckIn(selected.id, noteText); setSelected(null); }}>
                                            <CheckIcon />
                                            Mark as Present
                                        </button>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Ready to depart */}
                    <button
                        onClick={() => handleToggleReady(selectedRoute.id)}
                        className={`btn btn-block btn-lg ${selectedRoute.ready ? "btn-secondary" : "btn-primary"}`}
                    >
                        <HowToRegIcon />
                        <span>{selectedRoute.ready ? "All accounted for" : "Ready to depart?"}</span>
                    </button>
                </div>
            )}

        </main>
    );
}

import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ScheduleIcon from "@mui/icons-material/Schedule";
import { getProgrammes, getAttendanceSummary } from "../../services/api";

function RouteSection({ route }) {
    const pct = route.total > 0 ? Math.round((route.checkedIn / route.total) * 100) : 0;
    return (
        <section className="card">
            <div className="border-b border-edge px-4 py-3">
                <div className="flex items-center justify-between gap-2">
                    <h3 className="title truncate">{route.routeName || route.name}</h3>
                    {route.missing === 0 ? (
                        <span className="pill pill-ok shrink-0">All checked in</span>
                    ) : (
                        <span className="pill pill-warn shrink-0">{route.missing} missing</span>
                    )}
                </div>
            </div>
            <div className="space-y-3 p-4">
                <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                    <div className="flex flex-col items-center gap-1 rounded-xl bg-surface-2 px-3 py-2.5">
                        <span className="text-lg font-bold text-ink">{route.total}</span>
                        <span className="meta">Total</span>
                    </div>
                    <div className="flex flex-col items-center gap-1 rounded-xl bg-surface-2 px-3 py-2.5">
                        <span className="text-lg font-bold text-ok">{route.checkedIn}</span>
                        <span className="meta">Checked In</span>
                    </div>
                    <div className="flex flex-col items-center gap-1 rounded-xl bg-surface-2 px-3 py-2.5">
                        <span className="text-lg font-bold text-warn">{route.missing}</span>
                        <span className="meta">Missing</span>
                    </div>
                    <div className="flex flex-col items-center gap-1 rounded-xl bg-surface-2 px-3 py-2.5">
                        <span className="text-lg font-bold text-muted">{route.unidentified}</span>
                        <span className="meta">Unidentified</span>
                    </div>
                </div>
                <div className="progress">
                    <div className={`progress-fill ${route.missing === 0 ? "bg-ok" : ""}`} style={{ width: `${pct}%` }} />
                </div>
            </div>
        </section>
    );
}

export default function SummaryPage() {
    const { id } = useParams();
    const navigate = useNavigate();
    const [summary, setSummary] = useState(null);
    const [programmeName, setProgrammeName] = useState("");
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (!id) return;
        setLoading(true);
        Promise.all([
            getAttendanceSummary(id),
            getProgrammes(),
        ])
            .then(([summ, progs]) => {
                setSummary(summ);
                const p = progs.find((x) => x.id === id);
                setProgrammeName(p?.name || "Programme");
            })
            .catch((e) => setError(e.message))
            .finally(() => setLoading(false));
    }, [id]);

    if (loading) {
        return (
            <main className="page">
                <div className="mx-auto w-full max-w-2xl px-4 sm:px-6">
                    <div className="skeleton-card">
                        <div className="skeleton-text mb-3 w-1/3" />
                        <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                            <div className="skeleton h-16" />
                            <div className="skeleton h-16" />
                            <div className="skeleton h-16" />
                            <div className="skeleton h-16" />
                        </div>
                        <div className="skeleton h-2 w-full" />
                    </div>
                </div>
            </main>
        );
    }

    if (error) {
        return (
            <main className="page">
                <div className="mx-auto w-full max-w-2xl px-4 pt-8 sm:px-6">
                    <div className="banner banner-error">
                        <span>{error}</span>
                        <button className="btn btn-secondary btn-sm" onClick={() => navigate("/dashboard")}>
                            Back
                        </button>
                    </div>
                </div>
            </main>
        );
    }

    return (
        <main className="page">
            <header className="topbar">
                <div className="topbar-content">
                    <button className="back-btn" onClick={() => navigate("/dashboard")}>
                        <ArrowBackIcon />
                    </button>
                    <div className="min-w-0">
                        <h1 className="page-title truncate">Attendance Report</h1>
                        <p className="page-sub truncate">{programmeName}</p>
                    </div>
                </div>
            </header>

            <div className="mx-auto w-full max-w-2xl space-y-3 px-4 pb-6 sm:px-6">
                {(summary?.byRoute ?? []).length > 0 ? (
                    <div className="space-y-3">
                        {(summary.byRoute).map((r) => (
                            <RouteSection key={r.routeId} route={r} />
                        ))}
                    </div>
                ) : (
                    <div className="grid grid-cols-3 gap-3">
                        <div className="flex flex-col items-center gap-1 rounded-2xl bg-surface-2 px-3 py-4">
                            <span className="text-3xl font-bold tracking-tight text-ink">{summary?.total ?? 0}</span>
                            <span className="meta">Total</span>
                        </div>
                        <div className="flex flex-col items-center gap-1 rounded-2xl bg-surface-2 px-3 py-4">
                            <span className="text-3xl font-bold tracking-tight text-ok">{summary?.checkedIn ?? 0}</span>
                            <span className="meta">Checked In</span>
                        </div>
                        <div className="flex flex-col items-center gap-1 rounded-2xl bg-surface-2 px-3 py-4">
                            <span className="text-3xl font-bold tracking-tight text-warn">{summary?.missing ?? 0}</span>
                            <span className="meta">Missing</span>
                        </div>
                    </div>
                )}

                {summary?.unidentified > 0 && (
                    <section className="card">
                        <div className="border-b border-edge px-4 py-3">
                            <div className="flex items-center justify-between gap-2">
                                <h3 className="section-title">Unidentified Scans</h3>
                                <span className="meta shrink-0">{summary.unidentified} total</span>
                            </div>
                        </div>
                        <div className="card-divide">
                            {(summary.unidentifiedScans ?? []).map((s) => (
                                <div key={s.scanId} className="row">
                                    <div className="flex min-w-0 items-center gap-2">
                                        <ScheduleIcon className="text-muted" />
                                        <span className="meta shrink-0">
                                            {new Date(s.scannedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </span>
                                        <span className="truncate font-mono text-xs text-muted">{s.scanId.slice(0, 8)}…</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </section>
                )}
            </div>
        </main>
    );
}

